    def test_chk_m0_14_exchange_repeated_binding_substitutions_reject(self):
        exchange = {
            "schema_version": 1, "protocol": PROTOCOL, "state": "terminal",
            "request": self.request, "request_body_sha256": self.challenge["request_body_sha256"],
            "challenge": self.challenge, "consent_ack": self.ack,
            "authorization_proof": self.authorization_proof, "result": self.result,
            "safe_error": None, "consumed": True, "network_attempted": True,
            "response_retrievable": False,
        }
        validate_exchange(exchange)
        mutations = (
            ("body", lambda item: item.__setitem__("request_body_sha256", D)),
            ("scope", lambda item: item["challenge"].__setitem__("scope", {**item["challenge"]["scope"], "run_id": "changed"})),
            ("models", lambda item: item["result"].__setitem__("models", list(reversed(item["result"]["models"])))),
            ("sequence", lambda item: item["result"].__setitem__("sequence", 8)),
            ("chain", lambda item: item["challenge"].__setitem__("prior_chain_digest", D)),
            ("timing", lambda item: item["result"].__setitem__("issued_at", "2026-08-03T00:00:01Z")),
        )
        for label, mutate in mutations:
            item = copy.deepcopy(exchange); mutate(item)
            with self.subTest(label=label), self.assertRaisesRegex(ProviderDispatchError, "terminal_binding_invalid"):
                validate_exchange(item)
        digest_mutations = (
            ("ack", lambda item: item["consent_ack"].__setitem__("challenge_sha256", D), "consent_connection_invalid"),
            ("proof_challenge", lambda item: item["authorization_proof"].__setitem__("challenge_sha256", D), "terminal_binding_invalid"),
            ("challenge_digest", lambda item: item["result"].__setitem__("challenge_sha256", D), "terminal_binding_invalid"),
            ("assertion_digest", lambda item: item["result"].__setitem__("authority_assertion_sha256", D), "terminal_binding_invalid"),
            ("signer_digest", lambda item: item["result"].__setitem__("result_signer_sha256", D), "terminal_binding_invalid"),
        )
        for label, mutate, code in digest_mutations:
            item = copy.deepcopy(exchange); mutate(item)
            with self.subTest(label=label), self.assertRaisesRegex(ProviderDispatchError, code):
                validate_exchange(item)

    def test_chk_m0_15_result_schema_python_parity(self):
        schema = json.loads(RESULT_SCHEMA.read_text())
        corpus = [self.result]
        for field, value in (
            ("exit_code", 73), ("outcome", "unknown"), ("provider", "attacker"),
            ("generation_id", ""), ("serving_provider", "bad provider"),
            ("usage_sha256", D),
        ):
            item = copy.deepcopy(self.result); item[field] = value; corpus.append(item)
        for index, item in enumerate(corpus):
            try:
                validate_result(item)
                python_accepts = True
            except ProviderDispatchError:
                python_accepts = False
            with self.subTest(index=index):
                self.assertEqual(schema_matches(item, schema), python_accepts)

    def test_chk_m0_16_fd3_is_anonymous_pipe_verified_then_single_write(self):
        response_wire = frame32(canonical_json(self.authorization_proof)) + frame64(self.response) + frame32(canonical_json(self.result))
        try:
            saved = os.dup(3)
        except OSError:
            saved = None
        read_fd, write_fd = os.pipe()
        if read_fd == 3:
            replacement = os.dup(read_fd)
            os.close(read_fd)
            read_fd = replacement
        used = set()
        try:
            os.dup2(write_fd, 3)
            if write_fd != 3:
                os.close(write_fd)
            terminal = deliver_verified_fd3(
                3, used, response_wire, self.request, self.challenge,
                fixture_trust=True,
            )
            self.assertEqual(terminal, self.result)
            self.assertEqual(os.read(read_fd, len(self.response)), self.response)
            with self.assertRaisesRegex(ProviderDispatchError, "exchange_state_invalid"):
                deliver_verified_fd3(3, used, response_wire, self.request, self.challenge, fixture_trust=True)
        finally:
            os.close(read_fd)
            try:
                os.close(3)
            except OSError:
                pass
            if saved is not None:
                os.dup2(saved, 3); os.close(saved)
        try:
            partial_saved = os.dup(3)
        except OSError:
            partial_saved = None
        partial_read, partial_write = os.pipe()
        if partial_read == 3:
            replacement = os.dup(partial_read)
            os.close(partial_read)
            partial_read = replacement
        partial_used = set()
        try:
            os.dup2(partial_write, 3)
            if partial_write != 3:
                os.close(partial_write)
            with mock.patch("workflow_kernel.provider_dispatch.os.write", return_value=1) as write:
                with self.assertRaisesRegex(ProviderDispatchError, "result_verification_failed"):
                    deliver_verified_fd3(3, partial_used, response_wire, self.request, self.challenge, fixture_trust=True)
                self.assertEqual(partial_used, {3})
                with self.assertRaisesRegex(ProviderDispatchError, "exchange_state_invalid"):
                    deliver_verified_fd3(3, partial_used, response_wire, self.request, self.challenge, fixture_trust=True)
                write.assert_called_once()
        finally:
            os.close(partial_read)
            try:
                os.close(3)
            except OSError:
                pass
            if partial_saved is not None:
                os.dup2(partial_saved, 3)
                os.close(partial_saved)
        wrong_read, wrong_write = os.pipe()
        try:
            with self.assertRaisesRegex(ProviderDispatchError, "exchange_state_invalid"):
                validate_fd3(wrong_write, set())
        finally:
            os.close(wrong_read); os.close(wrong_write)
        def reject_at_fd3(source_fd):
            try:
                prior = os.dup(3)
            except OSError:
                prior = None
            try:
                os.dup2(source_fd, 3)
                with self.assertRaisesRegex(ProviderDispatchError, "exchange_state_invalid"):
                    validate_fd3(3, set())
            finally:
                try:
                    os.close(3)
                except OSError:
                    pass
                if prior is not None:
                    os.dup2(prior, 3); os.close(prior)
        with tempfile.TemporaryFile() as regular:
            reject_at_fd3(regular.fileno())
        left, right = socket.socketpair()
        try:
            reject_at_fd3(left.fileno())
        finally:
            left.close(); right.close()


